    seasonCue: { tempSensitive: true, notes: "The unbranched, pinkish-tan fertile spore stems with cone-like strobili emerge briefly in early spring before the green sterile shoots; that short window is the only harvest of the fertile shoots." },
    edibleParts: ["shoots"],
    edibility: "edible-with-caution",
    preparation: "Some foragers eat only the young fertile spring shoots and their strobili (spore cones), peeled and always cooked (boiled or steamed); the green sterile branched stems are more usually dried for tea, not eaten. Never eat raw. Keep portions small and occasional.",
    cautions: "Contains thiaminase, which destroys vitamin B1, and can accumulate selenium, silica and other minerals. Not for pregnant or nursing people, children, or prolonged/regular use. CRITICAL: positively distinguish from marsh horsetail (Equisetum palustre), which adds the toxic alkaloids palustrine and palustridiene and grows in the same wet ground.",
    toxicityNotes: "All horsetails contain thiaminase, so raw consumption can cause B1 deficiency (historically 'equisetosis' in livestock). E. arvense is only edible-with-caution. The look-alike E. palustre (marsh horsetail) is genuinely toxic and can be lethal to livestock; misidentification is the primary danger.",
    identification: {
      leaves: "True leaves reduced to rings of small dark teeth fused into a sheath at each stem joint; the plant photosynthesizes through its stems.",
      stem: "Two kinds: early unbranched pinkish-tan fertile stems (10-25 cm) topped by a cone-like strobilus, then later green, ridged, hollow sterile stems (to ~60 cm) with whorls of slender solid branches. On the sterile stem the FIRST branch segment is longer than the sheath it emerges from, and the central hollow is much larger than the small outer canals.",
      flowers: "None; reproduces by spores borne in the terminal cone (strobilus) of the fertile stem.",
      fruit: null,
      root: "Deep, far-creeping dark rhizomes, sometimes bearing small tubers.",
      aroma: "Fresh fertile shoots have a strong musty, barn-like smell that cooks off.",
      height: "Fertile stems ~10-25 cm; sterile stems ~20-60 cm.",
      keyFeatures: ["Jointed hollow stems with toothed sheaths", "Separate non-green fertile spring shoots with a spore cone", "Sterile stems with whorls of solid branches", "First branch segment longer than its sheath; large central hollow"],
    },
    lookalikes: [
      { name: "Marsh horsetail", scientific: "Equisetum palustre", danger: "toxic", distinguishingFeature: "Grows in wetter, boggier ground and carries the toxic alkaloids palustrine and palustridiene. On the sterile stem the lowest branch segment is SHORTER than (or equal to) the stem sheath, the central hollow is small (about the same size as the outer canals), and its strobili sit atop otherwise-green stems rather than on separate pale shoots. When in doubt, do not eat.", keyFeatures: ["Lowest branch segment shorter than the sheath", "Small central hollow", "Strobili borne on green stems", "Wet/boggy habitat", "Contains toxic alkaloids"] },
      { name: "Water horsetail", scientific: "Equisetum fluviatile", danger: "inedible", distinguishingFeature: "Very smooth, mostly unbranched stems with a very large central hollow, growing in standing water; not a recommended edible.", keyFeatures: ["Nearly branchless smooth stems", "Very large central hollow", "Grows in standing water"] },
      { name: "Scouring rush", scientific: "Equisetum hyemale", danger: "inedible", distinguishingFeature: "Evergreen, tall, unbranched, rough gritty stems used historically as an abrasive, not a food.", keyFeatures: ["Unbranched evergreen stems", "Rough, gritty texture"] },
    ],
    culinary: { flavor: "Cooked fertile shoots are mild, starchy and faintly sweet once the musty raw smell is boiled off; sterile stems make a green, grassy tea.", uses: "Peeled fertile shoots and strobili boiled as an occasional cooked vegetable; dried sterile stems steeped as a mineral tea (in moderation only).", preservation: "Dry sterile stems for tea; fertile shoots are best used fresh." },
