    seasonCue: { tempSensitive: true, notes: "Only the young, pre-flowering spring/early-summer shoots and leaf stalks are worth eating; they toughen quickly once the plant bolts to flower. Timing tracks snowmelt, so it is earlier at low elevation and later up high." },
    edibleParts: ["shoots", "stems", "young-leaves"],
